import { bigint, char, timestamp, uuid } from "drizzle-orm/pg-core";
import { sql } from "drizzle-orm";

/** Time ordered uuid generated by Postgres 18 (`uuidv7()`), so inserts stay index friendly. */
export const id = () =>
  uuid()
    .primaryKey()
    .default(sql`uuidv7()`);

export const createdAt = () => timestamp({ withTimezone: true }).notNull().defaultNow();

/** Money is an integer in minor units (cents). `bigint` in number mode: far above any real amount, no floats. */
export const cents = (name: string) => bigint(name, { mode: "number" });

/** ISO 4217 code. */
export const currencyCode = (name: string) => char(name, { length: 3 });
